--
-- Name: visit_conflicts; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.visit_conflicts AS
 WITH cells_with_staff AS (
         SELECT c.id AS cell_id,
            c.route_sheet_row_id,
            r.route_sheet_id,
            r.staff_id,
            COALESCE((r.staff_id)::text, ('name:'::text || COALESCE(r.staff_name, ''::text))) AS staff_key,
            (c.start_time)::time without time zone AS start_t,
            (c.end_time)::time without time zone AS end_t
           FROM (public.route_sheet_cells c
             JOIN public.route_sheet_rows r ON ((c.route_sheet_row_id = r.id)))
          WHERE ((c.is_break = false) AND (c.start_time ~ '^[0-2][0-9]:[0-5][0-9]$'::text) AND (c.end_time ~ '^[0-2][0-9]:[0-5][0-9]$'::text))
        )
 SELECT a.cell_id AS cell_a_id,
    b.cell_id AS cell_b_id,
    a.route_sheet_id,
    a.staff_id,
    a.staff_key,
    (a.start_t)::text AS a_start,
    (a.end_t)::text AS a_end,
    (b.start_t)::text AS b_start,
    (b.end_t)::text AS b_end
   FROM (cells_with_staff a
     JOIN cells_with_staff b ON (((a.staff_key = b.staff_key) AND (a.route_sheet_id = b.route_sheet_id) AND (a.cell_id < b.cell_id))))
  WHERE ((a.start_t, a.end_t) OVERLAPS (b.start_t, b.end_t));


ALTER VIEW public.visit_conflicts OWNER TO postgres;

